#!/usr/bin/env python3
"""Week 3 · harness for Task 3. Do not edit this file.

Replays a fixed query workload against a cache and reports four numbers:

    upstream    round trips actually made      (lower is better)
    hit rate    served without going upstream
    stale       answers served after their TTL had expired   (must be 0)
    sim time    what the workload would have cost in the real world

The upstream here is simulated - a fixed 20 ms round trip and a fixture of
names with realistic TTLs - so everyone's numbers are comparable and a slow
Wi-Fi does not decide your grade.

    python3 bench.py
    python3 bench.py --yours
"""
import argparse, random

RTT_MS = 20          # one simulated round trip
DURATION = 3600      # the workload spans one simulated hour
QUERIES = 1000

# name -> (address, ttl seconds).  A real mix: CDN names churn, infrastructure
# names sit still for a day.
FIXTURE = {
    "www.microsoft.com": ("23.49.206.40", 20),
    "www.cnn.com":       ("151.101.1.67", 30),
    "www.netflix.com":   ("207.45.72.1", 60),
    "www.spotify.com":   ("35.186.224.25", 120),
    "www.github.com":    ("140.82.112.4", 300),
    "www.wikipedia.org": ("198.35.26.96", 600),
    "www.korea.ac.kr":   ("163.152.6.10", 3600),
    "www.stanford.edu":  ("171.67.215.200", 3600),
    "dns.google":        ("8.8.8.8", 86400),
    "a.root-servers.net": ("198.41.0.4", 86400),
}


def workload(seed=246):
    """(time, name) pairs. Popular names are asked far more often - Zipf."""
    rng = random.Random(seed)
    names = list(FIXTURE)
    weights = [1 / (i + 1) for i in range(len(names))]
    times = sorted(rng.uniform(0, DURATION) for _ in range(QUERIES))
    return [(t, rng.choices(names, weights)[0]) for t in times]


class Upstream:
    """Simulated authoritative side. Counts how often it was bothered."""

    def __init__(self):
        self.calls = 0
        self.answered_at = {}

    def __call__(self, name):
        self.calls += 1
        address, ttl = FIXTURE[name]
        self.answered_at[name] = self.now
        return address, ttl


def run(cache_cls, label):
    up = Upstream()
    up.now = 0.0
    cache = cache_cls(up)

    fresh_until = {}        # name -> when the record we last fetched expires
    stale = 0
    for t, name in workload():
        up.now = t
        before = up.calls
        cache.lookup(name, t)
        if up.calls > before:                       # it went upstream
            fresh_until[name] = t + FIXTURE[name][1]
        elif t > fresh_until.get(name, -1):         # served from cache, expired
            stale += 1

    hits = QUERIES - up.calls
    print(f"  {label:<10} upstream {up.calls:>5}   "
          f"hit rate {hits / QUERIES:>6.1%}   "
          f"stale {stale:>4}   "
          f"sim time {up.calls * RTT_MS / 1000:>6.1f}s")
    return {"upstream": up.calls, "hits": hits, "stale": stale}


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--yours", action="store_true")
    a = p.parse_args()

    from task3_cache import BaselineCache
    print(f"\n  {QUERIES} queries over {DURATION // 60} simulated minutes, "
          f"{RTT_MS} ms per upstream round trip\n")
    base = run(BaselineCache, "baseline")

    if a.yours:
        from task3_cache import YourCache
        mine = run(YourCache, "yours")
        print()
        if mine["stale"] > 0:
            print(f"  {mine['stale']} stale answers. Nothing else counts until "
                  f"this is 0 - you are handing out expired records.")
        elif mine["upstream"] <= base["upstream"]:
            cut = 1 - mine["upstream"] / base["upstream"]
            print(f"  0 stale, upstream {cut:+.0%} vs baseline  ->  good")
            print(f"  For 'strong': in observation.md, work out the smallest "
                  f"number of\n  upstream queries any correct cache could make "
                  f"here, and why.")
        else:
            print(f"  0 stale, but {mine['upstream'] - base['upstream']} more "
                  f"upstream queries than the baseline.")
    print()


if __name__ == "__main__":
    main()
